PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY, balance INTEGER DEFAULT 0, last_salary TIMESTAMP DEFAULT CURRENT_TIMESTAMP, name TEXT);
CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, sender INTEGER, receiver INTEGER, amount INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, comment TEXT);
CREATE TABLE IF NOT EXISTS codes (id INTEGER PRIMARY KEY, code TEXT, owner_id INTEGER, used BOOLEAN, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, used_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_state (id INTEGER PRIMARY KEY, available_codes INTEGER DEFAULT 0, price REAL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_history (id INTEGER PRIMARY KEY AUTOINCREMENT, price REAL, available_codes INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_operations (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT, amount INTEGER, total REAL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, key_hash TEXT UNIQUE NOT NULL, owner_id INTEGER NOT NULL, name TEXT, scopes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMP, revoked BOOLEAN DEFAULT 0);
